// ctx is the context used by every service call in these tests.
var ctx = context.Background()

const (
	testAccount = "me@example.com"
	extraUserID = "u-zz-extra"
	extraUser   = "Zed Quinn"
)

// testLoc is a fixed zone (no tzdata dependency) so "today" is deterministic: 2026-11-23 09:30 local.
var testLoc = time.FixedZone("CST", -6*3600)

var baseTime = time.Date(2026, 11, 23, 9, 30, 0, 0, testLoc)

// ── fake clock ────────────────────────────────────────────────────────────────

type fakeClock struct {
	mu  sync.Mutex
	now time.Time
}

func (c *fakeClock) Now() time.Time {
	c.mu.Lock()
	defer c.mu.Unlock()
	return c.now
}
func (c *fakeClock) Location() *time.Location { return testLoc }
func (c *fakeClock) Advance(d time.Duration) {
	c.mu.Lock()
	c.now = c.now.Add(d)
	c.mu.Unlock()
}
func (c *fakeClock) ms() int64 { return c.Now().UnixMilli() }

// ── recording emitter ─────────────────────────────────────────────────────────

type emitted struct {
	Name    string
	Payload map[string]any // decoded from JSON, so tests do not depend on Go payload types
}

type recEmitter struct {
	mu sync.Mutex
	ev []emitted
}

func (e *recEmitter) Emit(name string, payload any) {
	b, _ := json.Marshal(payload)
	m := map[string]any{}
	_ = json.Unmarshal(b, &m)
	e.mu.Lock()
	e.ev = append(e.ev, emitted{Name: name, Payload: m})
	e.mu.Unlock()
}

func (e *recEmitter) named(name string) []emitted {
	e.mu.Lock()
	defer e.mu.Unlock()
	var out []emitted
	for _, x := range e.ev {
		if x.Name == name {
			out = append(out, x)
		}
	}
	return out
}

func (e *recEmitter) all() []emitted {
	e.mu.Lock()
	defer e.mu.Unlock()
	return append([]emitted(nil), e.ev...)
}

func (e *recEmitter) reset() {
	e.mu.Lock()
	e.ev = nil
	e.mu.Unlock()
}

// ── in-memory keyring ─────────────────────────────────────────────────────────

type memKeyring struct {
	mu     sync.Mutex
	m      map[string]string
	setErr error // returned by Set when non-nil (simulates "no Secret Service")
}

func newMemKeyring() *memKeyring { return &memKeyring{m: map[string]string{}} }

func (k *memKeyring) Get(account string) (string, error) {
	k.mu.Lock()
	defer k.mu.Unlock()
	v, ok := k.m[account]
	if !ok {
		return "", secrets.ErrNotFound
	}
	return v, nil
}

func (k *memKeyring) Set(account, secret string) error {
	k.mu.Lock()
	defer k.mu.Unlock()
	if k.setErr != nil {
		return k.setErr
	}
	k.m[account] = secret
	return nil
}

func (k *memKeyring) Delete(account string) error {
	k.mu.Lock()
	defer k.mu.Unlock()
	delete(k.m, account)
	return nil
}

func (k *memKeyring) items() map[string]string {
	k.mu.Lock()
	defer k.mu.Unlock()
	out := make(map[string]string, len(k.m))
	for a, s := range k.m {
		out[a] = s
	}
	return out
}

// accountsHolding returns the keychain accounts whose stored secret equals secret.
func (k *memKeyring) accountsHolding(secret string) []string {
	var out []string
	for a, s := range k.items() {
		if s == secret {
			out = append(out, a)
		}
	}
	return out
}

// ── network switch ────────────────────────────────────────────────────────────

type switchTransport struct {
	inner http.RoundTripper
	down  atomic.Bool
	calls atomic.Int64
}

func (t *switchTransport) RoundTrip(r *http.Request) (*http.Response, error) {
	t.calls.Add(1)
	if t.down.Load() {
		if r.Body != nil {
			_ = r.Body.Close()
		}
		return nil, &net.OpError{Op: "dial", Net: "tcp",
			Err: &net.DNSError{Err: "no such host", Name: r.URL.Hostname(), IsNotFound: true}}
	}
	return t.inner.RoundTrip(r)
}

// ── dispatcher recorder ───────────────────────────────────────────────────────

// recDispatcher counts every call the app (or the orchestrator's AfterSync hook) makes on the sink dispatcher.
type recDispatcher struct {
	inner sink.Dispatcher // late-bound (needs the services for its BuildFunc)
	mu    sync.Mutex
	calls []string
}

func (d *recDispatcher) note(s string) {
	d.mu.Lock()
	d.calls = append(d.calls, s)
	d.mu.Unlock()
}
func (d *recDispatcher) callCount() int {
	d.mu.Lock()
	defer d.mu.Unlock()
	return len(d.calls)
}
func (d *recDispatcher) Enqueue(c context.Context, sinkID, standupID int64, req sink.Request, cause, key string) (int64, error) {
	d.note("Enqueue")
	return d.inner.Enqueue(c, sinkID, standupID, req, cause, key)
}
func (d *recDispatcher) Flush(c context.Context, sinkID int64) error {
	d.note("Flush")
	return d.inner.Flush(c, sinkID)
}
func (d *recDispatcher) Retry(c context.Context, outboxID int64) error {
	d.note("Retry")
	return d.inner.Retry(c, outboxID)
}
func (d *recDispatcher) AfterSync(c context.Context, standupID, runID int64) error {
	d.note("AfterSync")
	return d.inner.AfterSync(c, standupID, runID)
}

// ── recorder sink (a registered fake sink kind with a secret) ────────────────

// recorderSink is a sink kind "recorder": NeedsSecret, records deliveries, and can be told to fail.
type recorderSink struct {
	mu        sync.Mutex
	delivered []sink.Delivery
	fail      bool
}

const recorderKind = "recorder"

var theRecorder = &recorderSink{}

func (r *recorderSink) Kind() string        { return recorderKind }
func (r *recorderSink) DisplayName() string { return "Recorder" }
func (r *recorderSink) Capabilities() sink.Capabilities {
	return sink.Capabilities{Current: true, Formats: []string{"json"}, NeedsSecret: true, Idempotent: true}
}
func (r *recorderSink) ConfigSchema() []sink.Field {
	return []sink.Field{{Key: "label", Label: "Label", Type: "text"}}
}
func (r *recorderSink) Validate(cfg map[string]string) error {
	if cfg["label"] == "bad" {
		return apperr.Validationf("label", "That label is not allowed.")
	}
	return nil
}
func (r *recorderSink) Deliver(_ context.Context, d sink.Delivery) (sink.Receipt, error) {
	r.mu.Lock()
	defer r.mu.Unlock()
	if r.fail {
		return sink.Receipt{}, apperr.New(apperr.SinkFailed, "The recorder refused the delivery.")
	}
	r.delivered = append(r.delivered, d)
	return sink.Receipt{Ref: "mem://" + d.Key}, nil
}
func (r *recorderSink) reset() {
	r.mu.Lock()
	r.delivered, r.fail = nil, false
	r.mu.Unlock()
}
func (r *recorderSink) setFail(v bool) { r.mu.Lock(); r.fail = v; r.mu.Unlock() }
func (r *recorderSink) deliveries() []sink.Delivery {
	r.mu.Lock()
	defer r.mu.Unlock()
	return append([]sink.Delivery(nil), r.delivered...)
}

// ── locked log buffer ─────────────────────────────────────────────────────────

type logBuf struct {
	mu sync.Mutex
	b  bytes.Buffer
}

func (l *logBuf) Write(p []byte) (int, error) {
	l.mu.Lock()
	defer l.mu.Unlock()
	return l.b.Write(p)
}
func (l *logBuf) String() string {
	l.mu.Lock()
	defer l.mu.Unlock()
	return l.b.String()
}

// ── fixture ───────────────────────────────────────────────────────────────────

// fxInfo is the parsed fixture plus the values the tests derive from it.
type fxInfo struct {
	fx            *jiratest.Fixture
	scrum         jiratest.FxBoard
	scrumProject  jiratest.FxProject
	kanban        jiratest.FxBoard
	kanbanProject jiratest.FxProject
	activeKey     string // an in-sprint issue of the scrum board that is not done and has an assignee
	activeAssign  string // its assignee account id
}

func (f *fxInfo) scrumID() string  { return strconv.Itoa(f.scrum.ID) }
func (f *fxInfo) kanbanID() string { return strconv.Itoa(f.kanban.ID) }

func buildFixture(tb testing.TB) *fxInfo {
	tb.Helper()
	var fx *jiratest.Fixture
	guard(tb, "jiratest.ParseFixture", func() {
		var err error
		fx, err = jiratest.ParseFixture(jiratest.DefaultFixture)
		if err != nil {
			tb.Fatalf("parse DefaultFixture: %v", err)
		}
	})
	if len(fx.Boards) == 0 || len(fx.Issues) == 0 {
		tb.Fatalf("jiratest.DefaultFixture is empty: run `go run ./cmd/fixturegen` (the app tests derive their expectations from it)")
	}
	info := &fxInfo{fx: fx}
	found := false
	for _, b := range fx.Boards {
		if b.Type == "scrum" && b.Sprint != nil {
			info.scrum, found = b, true
			break
		}
	}
	if !found {
		tb.Fatalf("DefaultFixture has no scrum board with a sprint")
	}
	for _, p := range fx.Projects {
		if p.Key == info.scrum.ProjectKey {
			info.scrumProject = p
		}
	}
	if info.scrumProject.Key == "" {
		tb.Fatalf("DefaultFixture: board %q references unknown project %q", info.scrum.Name, info.scrum.ProjectKey)
	}
	// An in-sprint, assigned, not-done issue of the scrum board.
	doneStatuses := map[string]bool{}
	if n := len(info.scrum.Columns); n > 0 {
		for _, s := range info.scrum.Columns[n-1].Statuses {
			doneStatuses[s] = true
		}
	}
	for _, is := range fx.Issues {
		if is.Board != info.scrum.ID || !is.InSprint || is.Assignee == "" || len(is.History) == 0 {
			continue
		}
		if doneStatuses[is.History[len(is.History)-1].Status] {
			continue
		}
		info.activeKey, info.activeAssign = is.Key, is.Assignee
		break
	}
	if info.activeKey == "" {
		tb.Fatalf("DefaultFixture has no in-sprint, assigned, not-done issue on board %q", info.scrum.Name)
	}
	// Appended data (see the SPEC-NOTE at the top of the file).
	info.kanbanProject = jiratest.FxProject{ID: "19001", Key: "OPSX", Name: "Operations X"}
	info.kanban = jiratest.FxBoard{
		ID: 9002, Name: "OPSX board", Type: "kanban", ProjectKey: "OPSX", FilterID: 9902,
		Columns: []jiratest.FxColumn{
			{Name: "Ops Queue", Statuses: []string{"Ops Queue"}},
			{Name: "Ops Active", Statuses: []string{"Ops Active"}},
			{Name: "Ops Done", Statuses: []string{"Ops Done"}},
		},
	}
	fx.Projects = append(fx.Projects, info.kanbanProject)
	fx.Boards = append(fx.Boards, info.kanban)
	fx.Users = append(fx.Users, jiratest.FxUser{AccountID: extraUserID, DisplayName: extraUser})
	fx.Issues = append(fx.Issues,
		jiratest.FxIssue{Key: "OPSX-1", Type: "Task", Summary: "Rotate certificates", Board: 9002,
			History: []jiratest.FxHistory{{Status: "Ops Queue", Days: 2}, {Status: "Ops Active", Days: 1}}},
		jiratest.FxIssue{Key: "OPSX-2", Type: "Task", Summary: "Patch the proxy", Board: 9002,
			History: []jiratest.FxHistory{{Status: "Ops Queue", Days: 3}}},
	)
	return info
}

// ── the app under test ────────────────────────────────────────────────────────

type appOpt func(*appCfg)

type appCfg struct {
	fileDB  bool
	latency time.Duration
}

// withFileDB uses a file-backed DB (raw-bytes scans, DBBytes).
func withFileDB() appOpt { return func(c *appCfg) { c.fileDB = true } }

// withLatency makes every fake Jira response take d (so runs are observably "in flight").
func withLatency(d time.Duration) appOpt { return func(c *appCfg) { c.latency = d } }

type testApp struct {
	t     *testing.T
	Clock *fakeClock
	DB    *store.DB
	Em    *recEmitter
	KR    *memKeyring
	Fake  *jiratest.Server
	Net   *switchTransport
	Fx    *fxInfo
	Log   *logBuf
	Disp  *recDispatcher
	Paths paths.Paths

	SinkDir string // target folder for file sinks

	// rewired by wire()
	Deps *app.Deps
	Svc  *app.Services
	Orch *syncpkg.Orchestrator

	opened []string // URLs passed to Deps.OpenURL
	openMu sync.Mutex
}

// guard turns a panicking Wave 0 stub into a clean test failure instead of killing the whole test binary.
func guard(tb testing.TB, what string, fn func()) {
	tb.Helper()
	defer func() {
		if r := recover(); r != nil {
			tb.Fatalf("dependency not implemented yet (%s): %v", what, r)
		}
	}()
	fn()
}

func newTestApp(t *testing.T, opts ...appOpt) *testApp {
	t.Helper()
	cfg := appCfg{}
	for _, o := range opts {
		o(&cfg)
	}
	ta := &testApp{t: t, Clock: &fakeClock{now: baseTime}, Em: &recEmitter{}, KR: newMemKeyring(), Log: &logBuf{}}
	ta.Paths = paths.Paths{Data: t.TempDir(), Logs: t.TempDir()}
	ta.SinkDir = t.TempDir()
	ta.Fx = buildFixture(t)

	guard(t, "storetest.Open", func() {
		if cfg.fileDB {
			ta.DB = storetest.OpenFile(t, ta.Clock.Now)
		} else {
			ta.DB = storetest.Open(t, ta.Clock.Now)
		}
	})
	guard(t, "jiratest.NewServer", func() {
		ta.Fake = jiratest.NewServer(t, ta.Fx.fx, jiratest.Options{Now: baseTime, Loc: testLoc, Latency: cfg.latency})
	})
	guard(t, "sink.Register(file.New())", func() { sink.Register(file.New()) })
	theRecorder.reset()
	sink.Register(theRecorder)
	t.Cleanup(theRecorder.reset)
	source.Register(jira.Kind, jira.New, jira.IssueURL)

	ta.Net = &switchTransport{inner: http.DefaultTransport.(*http.Transport).Clone()}
	ta.wire()
	return ta
}

// wire (re)builds Deps, Services and the Orchestrator over the same DB, keyring and fake (a simulated restart).
func (ta *testApp) wire() {
	t := ta.t
	t.Helper()
	if ta.Orch != nil {
		_ = ta.Orch.Shutdown(ctx)
	}
	logger := slog.New(slog.NewTextHandler(ta.Log, &slog.HandlerOptions{Level: slog.LevelDebug}))
	httpClient := &http.Client{Transport: ta.Net}
	srcOpts := source.Options{HTTP: httpClient, Logger: logger, Now: ta.Clock.Now, UserAgent: "Cuisle/test (test)"}

	ta.Disp = &recDispatcher{}
	d := &app.Deps{
		DB: ta.DB, Keyring: ta.KR, Sinks: ta.Disp, Emitter: ta.Em, Clock: ta.Clock, Logger: logger, Paths: ta.Paths,
		SourceOpts: srcOpts, HTTP: httpClient, Now: ta.Clock.Now,
		OpenURL: func(u string) error {
			ta.openMu.Lock()
			ta.opened = append(ta.opened, u)
			ta.openMu.Unlock()
			return nil
		},
	}
	guard(t, "settings.New", func() { d.Settings = settings.New(ta.DB, ta.Clock.Now) })
	guard(t, "sync.New", func() {
		d.Sync = syncpkg.New(syncpkg.Options{
			DB: ta.DB, Keyring: ta.KR, Emitter: ta.Em, Clock: ta.Clock, Logger: logger, SourceOpts: srcOpts,
			AfterSync: func(c context.Context, standupID, runID int64) { _ = ta.Disp.AfterSync(c, standupID, runID) },
		})
	})
	ta.Deps, ta.Orch = d, d.Sync
	ta.Svc = app.NewServices(d)

	build := func(c context.Context, standupID int64, req sink.Request) (export.Document, []byte, string, string, error) {
		v, err := ta.Svc.Standup.View(c, standupID)
		if err != nil {
			return export.Document{}, nil, "", "", err
		}
		sc, err := ta.Svc.Config.Get(c, standupID)
		if err != nil {
			return export.Document{}, nil, "", "", err
		}
		meta := export.Meta{
			GeneratedAt: ta.Clock.Now(), Version: "test", Kind: req.Kind, SourceKind: jira.Kind, BaseURL: ta.Fake.URL,
			StandupID: standupID, Name: v.Name, SpaceKey: v.SpaceKey, BoardName: v.BoardName, BoardKind: v.BoardType,
			Scope: v.Scope, Timezone: testLoc,
		}
		if sc.Space != nil {
			meta.SpaceName = sc.Space.Name
		}
		if sc.Board != nil {
			meta.BoardID = sc.Board.ID
		}
		doc := export.Build([]view.StandupView{v}, meta)
		raw, err := export.Encode(doc)
		return doc, raw, v.SpaceKey, v.Today, err
	}
	guard(t, "sink.NewDispatcher", func() {
		ta.Disp.inner = sink.NewDispatcher(ta.DB, ta.KR, build, sink.DispatcherOptions{
			Logger: logger, Now: ta.Clock.Now, Sleep: func(time.Duration) {},
		})
	})
	t.Cleanup(func() { _ = d.Sync.Shutdown(context.Background()) })
}

// restart simulates quitting and relaunching the app: new Deps/Services/Orchestrator over the same DB and fake.
func (ta *testApp) restart() {
	ta.t.Helper()
	ta.Em.reset()
	ta.wire()
}

func (ta *testApp) openedURLs() []string {
	ta.openMu.Lock()
	defer ta.openMu.Unlock()
	return append([]string(nil), ta.opened...)
}

// ── flows ─────────────────────────────────────────────────────────────────────

func (ta *testApp) connectInput() app.ConnectInput {
	return app.ConnectInput{Source: jira.Kind, BaseURL: ta.Fake.URL, Account: testAccount, Secret: jiratest.Token}
}

func (ta *testApp) connect() app.Connection {
	ta.t.Helper()
	c, err := ta.Svc.Connection.Connect(ctx, ta.connectInput())
	noErr(ta.t, err, "Connect")
	return c
}

// newStandup creates a standup on the given project/board through the public API (online).
func (ta *testApp) newStandup(project jiratest.FxProject, board jiratest.FxBoard) view.StandupConfig {
	t := ta.t
	t.Helper()
	cfg, err := ta.Svc.Config.Create(ctx)
	noErr(t, err, "Config.Create")
	spaces, err := ta.Svc.Connection.SearchSpaces(ctx, project.Key)
	noErr(t, err, "SearchSpaces")
	var space *view.SpaceOption
	for i := range spaces {
		if spaces[i].Key == project.Key {
			space = &spaces[i]
		}
	}
	if space == nil {
		t.Fatalf("SearchSpaces(%q) did not return the project: %+v", project.Key, spaces)
	}
	_, err = ta.Svc.Config.SetSpace(ctx, cfg.ID, space.ID)
	noErr(t, err, "SetSpace")
	boards, err := ta.Svc.Connection.SearchBoards(ctx, project.Key, "")
	noErr(t, err, "SearchBoards")
	var bo *view.BoardOption
	for i := range boards {
		if boards[i].ID == strconv.Itoa(board.ID) {
			bo = &boards[i]
		}
	}
	if bo == nil {
		t.Fatalf("SearchBoards(%q) did not return board %d: %+v", project.Key, board.ID, boards)
	}
	out, err := ta.Svc.Config.SetBoard(ctx, cfg.ID, bo.ID)
	noErr(t, err, "SetBoard")
	return out
}

// syncNow runs a full sync through the service and waits for it to finish.
func (ta *testApp) syncNow(standupID int64) int64 {
	t := ta.t
	t.Helper()
	run, err := ta.Svc.Sync.Start(ctx, standupID, syncpkg.ModeFull)
	noErr(t, err, "Sync.Start")
	if run <= 0 {
		t.Fatalf("Sync.Start returned run id %d, want > 0", run)
	}
	ta.Orch.Wait(standupID)
	return run
}

// scrumStandup is the common fixture state: connected, scrum standup configured and synced once.
func (ta *testApp) scrumStandup() int64 {
	ta.t.Helper()
	ta.connect()
	cfg := ta.newStandup(ta.Fx.scrumProject, ta.Fx.scrum)
	ta.syncNow(cfg.ID)
	return cfg.ID
}

// kanbanStandup adds a configured, never-synced kanban standup (needs a connection).
func (ta *testApp) kanbanStandup() int64 {
	ta.t.Helper()
	return ta.newStandup(ta.Fx.kanbanProject, ta.Fx.kanban).ID
}

// networkCalls is the number of HTTP round trips attempted since the app was built (successful or not).
func (ta *testApp) networkCalls() int64 { return ta.Net.calls.Load() }

// assertNoNetwork fails when anything touched the network since mark (a value from networkCalls) or when the fake's
// request log is not empty (call ta.Fake.ResetRequests() right after taking the mark).
func (ta *testApp) assertNoNetwork(mark int64, what string) {
	ta.t.Helper()
	if n := ta.networkCalls() - mark; n != 0 {
		ta.t.Errorf("%s: %d HTTP round trips were attempted, want 0", what, n)
	}
	if reqs := ta.Fake.Requests(); len(reqs) != 0 {
		ta.t.Errorf("%s: the fake Jira saw %d requests, want 0: %+v", what, len(reqs), reqs)
	}
}

