// ── assertions ────────────────────────────────────────────────────────────────

func noErr(tb testing.TB, err error, what string) {
	tb.Helper()
	if err != nil {
		tb.Fatalf("%s: unexpected error: %v", what, err)
	}
}

// wantCode asserts err is a typed *apperr.Error with the given code (not a raw error that merely maps to it).
func wantCode(tb testing.TB, err error, code apperr.Code, what string) *apperr.Error {
	tb.Helper()
	if err == nil {
		tb.Fatalf("%s: got nil error, want apperr %q", what, code)
	}
	var ae *apperr.Error
	if !errors.As(err, &ae) {
		tb.Fatalf("%s: error %T %q is not an *apperr.Error; services must return typed errors", what, err, err)
	}
	if ae.Code != code {
		tb.Fatalf("%s: error code = %q (%s), want %q", what, ae.Code, ae.Message, code)
	}
	return ae
}

func wantCodeOneOf(tb testing.TB, err error, what string, codes ...apperr.Code) *apperr.Error {
	tb.Helper()
	if err == nil {
		tb.Fatalf("%s: got nil error, want one of %v", what, codes)
	}
	var ae *apperr.Error
	if !errors.As(err, &ae) {
		tb.Fatalf("%s: error %T %q is not an *apperr.Error", what, err, err)
	}
	for _, c := range codes {
		if ae.Code == c {
			return ae
		}
	}
	tb.Fatalf("%s: error code = %q (%s), want one of %v", what, ae.Code, ae.Message, codes)
	return nil
}

// scanDBForText fails when needle appears in any text/blob cell of any table.
func scanDBForText(tb testing.TB, db *store.DB, needle string) {
	tb.Helper()
	rows, err := db.R.Query(`SELECT name FROM sqlite_master WHERE type = 'table' AND name NOT LIKE 'sqlite_%'`)
	noErr(tb, err, "list tables")
	var tables []string
	for rows.Next() {
		var n string
		noErr(tb, rows.Scan(&n), "scan table name")
		tables = append(tables, n)
	}
	noErr(tb, rows.Err(), "tables rows")
	_ = rows.Close()
	if len(tables) == 0 {
		tb.Fatalf("no tables found: DB not migrated?")
	}
	for _, table := range tables {
		scanTable(tb, db.R, table, needle)
	}
}

func scanTable(tb testing.TB, q *sql.DB, table, needle string) {
	tb.Helper()
	rows, err := q.Query(`SELECT * FROM "` + table + `"`)
	noErr(tb, err, "select "+table)
	defer rows.Close()
	cols, _ := rows.Columns()
	for rows.Next() {
		vals := make([]any, len(cols))
		ptrs := make([]any, len(cols))
		for i := range vals {
			ptrs[i] = &vals[i]
		}
		noErr(tb, rows.Scan(ptrs...), "scan "+table)
		for i, v := range vals {
			var s string
			switch x := v.(type) {
			case string:
				s = x
			case []byte:
				s = string(x)
			default:
				continue
			}
			if strings.Contains(s, needle) {
				tb.Errorf("table %s column %s contains the secret %q", table, cols[i], needle)
			}
		}
	}
}

// scanFileBytes fails when the secret appears in the DB file or its WAL (raw bytes, testing.md "Security").
func scanFileBytes(tb testing.TB, db *store.DB, needles ...string) {
	tb.Helper()
	if db.Path == "" {
		tb.Fatalf("scanFileBytes needs a file DB")
	}
	for _, p := range []string{db.Path, db.Path + "-wal"} {
		b, err := os.ReadFile(p)
		if err != nil {
			continue // the WAL may not exist
		}
		for _, n := range needles {
			if bytes.Contains(b, []byte(n)) {
				tb.Errorf("%s contains the secret %q", p, n)
			}
		}
	}
}

func contains(ss []string, s string) bool {
	for _, x := range ss {
		if x == s {
			return true
		}
	}
	return false
}

func fmtJSON(v any) string {
	b, err := json.Marshal(v)
	if err != nil {
		return fmt.Sprintf("<%v>", err)
	}
	return string(b)
}

func ptr[T any](v T) *T { return &v }

func fakeToken() string { return jiratest.Token }

